(function syncRefundDecisionToCase(current, previous) {
    if (current.getValue('decision') === previous.getValue('decision')) {
        return;
    }

    // Copy-down: auto-approved refunds approve the full requested amount.
    if (current.getValue('decision') === 'auto_approved' && !current.getValue('amount_approved')) {
        current.setValue('amount_approved', current.getValue('amount_requested'));
        current.update();
    }

    var caseGr = new GlideRecord('sn_customerservice_case');
    if (!caseGr.get(current.getValue('case'))) {
        return;
    }

    var decision = current.getValue('decision');
    if (decision === 'auto_escalated') {
        caseGr.setValue('x_2145749_qc_fraud_review_required', current.getValue('fraud_flagged') === 'true');
        caseGr.work_notes = 'Refund request ' + current.getValue('number') +
            ' escalated by the Automated Resolution Engine: ' + current.getValue('decision_notes');
    } else if (decision === 'auto_approved') {
        caseGr.setValue('x_2145749_qc_auto_resolved', true);
        var requestType = current.getValue('request_type');
        caseGr.setValue('x_2145749_qc_resolution_type', requestType === 'reorder' ? 'reorder' : 'full_refund');
        caseGr.work_notes = 'Refund request ' + current.getValue('number') + ' auto-approved by the Automated Resolution Engine.';
    } else if (decision === 'manually_approved' || decision === 'manually_denied') {
        caseGr.work_notes = 'Refund request ' + current.getValue('number') + ' ' + decision.replace('_', ' ') + ' by an agent.';
    }
    caseGr.update();
})(current, previous);
